public sealed class DomainExceptionHandler(IProblemDetailsService problems) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext http, Exception ex, CancellationToken ct)
    {
        if (ex is not DomainRuleViolation rule) return false;      // let the next handler try
        http.Response.StatusCode = StatusCodes.Status422UnprocessableEntity;
        return await problems.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = http,
            Exception = ex,
            ProblemDetails = { Title = "Business rule violated", Detail = rule.SafeMessage, Extensions = { ["errorCode"] = rule.Code } }
        });
    }
}

public sealed class FallbackExceptionHandler(ILogger<FallbackExceptionHandler> log, IProblemDetailsService problems) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext http, Exception ex, CancellationToken ct)
    {
        log.LogError(ex, "Unhandled exception");                      // logged once, with the trace id from the activity
        return await problems.TryWriteAsync(new() { HttpContext = http, Exception = ex,
            ProblemDetails = { Title = "Something went wrong", Detail = "Please try again. Quote the trace id if you contact us." } });
    }
}
