public sealed class SettlementWorker(IConsumer consumer, ILogger<SettlementWorker> log, TimeProvider clock) : BackgroundService, IHostedLifecycleService
{
    public DateTimeOffset LastProgress { get; private set; }

    public async Task StartingAsync(CancellationToken ct) => await consumer.ValidateTopologyAsync(ct);   // fail fast before serving
    public Task StartedAsync(CancellationToken ct) => Task.CompletedTask;
    public Task StoppingAsync(CancellationToken ct) { log.LogInformation("Draining settlement worker"); return Task.CompletedTask; }
    public Task StoppedAsync(CancellationToken ct) => Task.CompletedTask;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var msg in consumer.ReadAllAsync(stoppingToken))
        {
            try { await ProcessAsync(msg, stoppingToken); await consumer.AckAsync(msg, stoppingToken); }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                log.LogWarning(ex, "Settlement {Id} failed, sending to retry", msg.Id);
                await consumer.RetryLaterAsync(msg, stoppingToken);          // per-message handling, loop keeps running
            }
            LastProgress = clock.GetUtcNow();
        }
    }
}

public sealed class WorkerProgressCheck(SettlementWorker w, TimeProvider clock) : IHealthCheck
{
    public Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext c, CancellationToken ct) =>
        Task.FromResult(clock.GetUtcNow() - w.LastProgress < TimeSpan.FromMinutes(5)
            ? HealthCheckResult.Healthy() : HealthCheckResult.Unhealthy("No settlement progress for 5 minutes"));
}
